const workflow = $input.first().json;

// --------------------------------------------------
// CONFIGURATION
// --------------------------------------------------

const suspiciousKeys = {
  // Field names that normally hold a secret.
  secrets: [
    'password',
    'passwd',
    'pwd',
    'secret',
    'api_key',
    'apikey',
    'apiKey',
    'access_token',
    'accessToken',
    'auth_token',
    'authToken',
    'client_secret',
    'clientSecret',
    'private_key',
    'privateKey',
    'token'
  ],

  // n8n metadata that should not be published.
  n8nMetadata: {
    webhookId: 'webhook_identifier',
    dataTableId: 'datatable_identifier',
    documentId: 'document_identifier',
    cachedResultUrl: 'datatable_url',
    instanceId: 'instance_identifier',
    versionId: 'workflow_version_identifier'
  }
};

// { name, value } pairs (HTTP headers, query params, Set fields...)
// whose NAME suggests that the VALUE is a secret.
const secretFieldNames =
  /^(authorization|proxy-authorization|x-api-key|api[-_]?key|x-auth-token|(access|auth|refresh)[-_]?token|token|secret|client[-_]?secret|password|passwd|pwd)$/i;

// Types whose children must not be scanned again
// (the whole resource locator is redacted at once).
const resourceTypes = ['datatable_identifier', 'document_identifier'];

const findings = [];
const seen = new Set();


// --------------------------------------------------
// HELPERS
// --------------------------------------------------

// A "literal" value is something that could really be a secret:
// not empty and not an n8n expression (those start with "=").
function isLiteral(value) {
  if (value === null || value === undefined || value === '') return false;
  if (typeof value === 'boolean') return false;
  if (typeof value === 'string' && value.trim().startsWith('=')) return false;
  return true;
}

// Human readable path, e.g. nodes[2].parameters.password
function formatPath(parts) {
  return parts
    .map((part, i) =>
      typeof part === 'number' ? `[${part}]` : (i ? `.${part}` : part)
    )
    .join('');
}

// Register a finding only once per path.
// pathParts is an array (not a dotted string) so keys that contain
// dots, like node names, never break the lookup later.
function addFinding(pathParts, key, type) {
  const id = JSON.stringify(pathParts);
  if (seen.has(id)) return;
  seen.add(id);

  findings.push({
    path: formatPath(pathParts),
    pathParts,
    key,
    type
    // The value is intentionally NOT stored, so the list
    // of findings is always safe to look at or share.
  });
}


// --------------------------------------------------
// PATTERN DETECTION BY VALUE
// --------------------------------------------------
// Only strings that LOOK like a credential are matched.
// Header-style patterns (Bearer / Basic) must match the whole
// string, so normal text such as comments or sticky notes that
// mention "Basic authentication" is never redacted.
// --------------------------------------------------

function detectValuePattern(value) {

  // Only analyze string type values.
  if (typeof value !== 'string') {
    return null;
  }

  // CONNECTION STRINGS
  const connectionStringPattern =
    /\b(?:postgres(?:ql)?|mysql|mongodb(?:\+srv)?)\:\/\/[^\/\s:@]+:[^\/\s@]+@[^\/\s]+/i;

  if (connectionStringPattern.test(value)) {
    return 'connection_string';
  }

  // URL WITH CREDENTIALS
  const urlCredentialsPattern =
    /\bhttps?:\/\/[^\/\s:@]+:[^\/\s@]+@[^\/\s]+/i;

  if (urlCredentialsPattern.test(value)) {
    return 'url_credentials';
  }

  // JWT
  const jwtPattern =
    /\beyJ[a-zA-Z0-9_-]*\.[a-zA-Z0-9_-]*\.[a-zA-Z0-9_-]*\b/;

  if (jwtPattern.test(value)) {
    return 'jwt';
  }

  // PRIVATE KEYS
  const privateKeyPattern =
    /-----BEGIN [A-Z0-9 ]*PRIVATE KEY-----/;

  if (privateKeyPattern.test(value)) {
    return 'private_key';
  }

  // BASIC AUTHENTICATION
  // Whole string, e.g. "Basic dXNlcjpwYXNz" (an optional leading "="
  // is allowed). Expressions like "Basic {{ $json.x }}" are ignored.
  const basicAuthPattern =
    /^\s*=?\s*Basic\s+(?!\{\{|\$)[A-Za-z0-9+/]{8,}={0,2}\s*$/i;

  if (basicAuthPattern.test(value)) {
    return 'basic_auth';
  }

  // BEARER TOKENS
  // Whole string, e.g. "Bearer abc123...". Expressions like
  // "Bearer {{ $json.token }}" are ignored.
  const bearerTokenPattern =
    /^\s*=?\s*Bearer\s+(?!\{\{|\$)[A-Za-z0-9\-._~+\/]{8,}=*\s*$/i;

  if (bearerTokenPattern.test(value)) {
    return 'bearer_token';
  }

  return null;
}


// --------------------------------------------------
// RECURSIVE WORKFLOW TRAVERSAL
// --------------------------------------------------

function scan(value, pathParts = [], insideCredentials = false) {

  // Arrays
  if (Array.isArray(value)) {

    value.forEach((item, index) => {
      scan(item, [...pathParts, index], insideCredentials);
    });

    return;
  }


  // Objects
  if (value !== null && typeof value === 'object') {

    // ----------------------------------------------
    // 0. { name, value } PAIRS WITH A SECRET NAME
    // ----------------------------------------------
    // Example: an HTTP header { name: "apikey", value: "..." }

    if (
      typeof value.name === 'string' &&
      secretFieldNames.test(value.name) &&
      isLiteral(value.value) &&
      typeof value.value !== 'object'
    ) {
      addFinding([...pathParts, 'value'], 'value', 'secret');
    }


    for (const [key, child] of Object.entries(value)) {

      const currentPath = [...pathParts, key];

      let type = null;


      // ----------------------------------------------
      // 1. DETECT SECRETS BY FIELD NAME
      // ----------------------------------------------

      if (suspiciousKeys.secrets.includes(key) && isLiteral(child)) {
        type = 'secret';
      }


      // ----------------------------------------------
      // 2. DETECT N8N SPECIFIC METADATA
      // ----------------------------------------------

      if (suspiciousKeys.n8nMetadata[key] && isLiteral(child)) {
        type = suspiciousKeys.n8nMetadata[key];
      }


      // ----------------------------------------------
      // 3. DETECT CREDENTIAL ID
      // ----------------------------------------------

      if (insideCredentials && key === 'id') {
        type = 'credential_identifier';
      }


      // ----------------------------------------------
      // 4. DETECT PATTERNS IN VALUE
      // ----------------------------------------------

      const valuePattern = detectValuePattern(child);

      if (valuePattern) {
        type = valuePattern;
      }


      // ----------------------------------------------
      // REGISTER FINDING
      // ----------------------------------------------

      if (type) {

        addFinding(currentPath, key, type);

        // The whole value is redacted at once, so there is
        // no need to look inside it (this also avoids
        // detecting cachedResultUrl separately).
        if (
          resourceTypes.includes(type) ||
          (type === 'secret' && typeof child === 'object')
        ) {
          continue;
        }
      }


      // ----------------------------------------------
      // DETERMINE CREDENTIALS CONTEXT
      // ----------------------------------------------

      const nextInsideCredentials =
        insideCredentials || key === 'credentials';


      scan(child, currentPath, nextInsideCredentials);
    }
  }
}


// --------------------------------------------------
// START SCAN
// --------------------------------------------------

scan(workflow);


// --------------------------------------------------
// RESULT
// --------------------------------------------------

return [
  {
    json: {
      originalWorkflow: workflow,
      findings,
      totalFindings: findings.length
    }
  }
];

const input = $input.first().json;

const originalWorkflow = input.originalWorkflow;
const findings = input.findings;


// --------------------------------------------------
// CONFIGURATION
// --------------------------------------------------

// Remove the pinned (test) data of every node.
// It usually contains real execution data: phone numbers,
// names, messages, emails...
const CLEAR_PIN_DATA = true;

// Replacement text for each type of finding.
const placeholders = {
  secret: '[REDACTED_SECRET]',
  connection_string: '[REDACTED_CONNECTION_STRING]',
  url_credentials: '[REDACTED_URL_CREDENTIALS]',
  jwt: '[REDACTED_JWT]',
  basic_auth: '[REDACTED_BASIC_AUTH]',
  bearer_token: '[REDACTED_BEARER_TOKEN]',
  private_key: '[REDACTED_PRIVATE_KEY]',
  webhook_identifier: '[REDACTED_WEBHOOK_ID]',
  workflow_version_identifier: '[REDACTED_VERSION_ID]',
  instance_identifier: '[REDACTED_INSTANCE_ID]',
  credential_identifier: '[REDACTED_CREDENTIAL_ID]',
  datatable_url: '[REDACTED_URL]'
};

// Resource locators ({ __rl, value, cachedResultUrl, ... }):
// only the sensitive parts are replaced, the structure is kept.
const resourcePlaceholders = {
  datatable_identifier: '[REDACTED_DATATABLE_ID]',
  document_identifier: '[REDACTED_DOCUMENT_ID]'
};


// Create an independent copy of the workflow.
// This way we never modify originalWorkflow.
const sanitizedWorkflow = JSON.parse(
  JSON.stringify(originalWorkflow)
);


// --------------------------------------------------
// HELPERS
// --------------------------------------------------

// Read the value located at a path (array of keys / indexes).
function getAtPath(object, parts) {
  return parts.reduce(
    (current, part) =>
      current !== null && current !== undefined ? current[part] : undefined,
    object
  );
}

// Replace the value located at a path.
// Returns false if the path does not exist anymore.
function replaceAtPath(object, parts, newValue) {
  const parent = getAtPath(object, parts.slice(0, -1));

  if (parent === null || typeof parent !== 'object') {
    return false;
  }

  parent[parts[parts.length - 1]] = newValue;
  return true;
}


// --------------------------------------------------
// REDACTION
// --------------------------------------------------

const redactedByType = {};
const details = [];

// Findings inside pinData are skipped: it is cleared as a whole below.
const relevantFindings = findings.filter(
  finding => !(CLEAR_PIN_DATA && finding.pathParts[0] === 'pinData')
);

for (const finding of relevantFindings) {

  let done = false;

  if (resourcePlaceholders[finding.type]) {

    const target = getAtPath(sanitizedWorkflow, finding.pathParts);

    if (target !== null && typeof target === 'object') {

      // Resource locator: keep the structure, redact only
      // the id and the cached URL.
      if ('value' in target) {
        target.value = resourcePlaceholders[finding.type];
      }

      if ('cachedResultUrl' in target) {
        target.cachedResultUrl = '[REDACTED_URL]';
      }

      done = true;

    } else if (typeof target === 'string') {

      done = replaceAtPath(
        sanitizedWorkflow,
        finding.pathParts,
        resourcePlaceholders[finding.type]
      );
    }

  } else if (placeholders[finding.type]) {

    done = replaceAtPath(
      sanitizedWorkflow,
      finding.pathParts,
      placeholders[finding.type]
    );
  }

  if (done) {
    redactedByType[finding.type] = (redactedByType[finding.type] || 0) + 1;
    details.push({ path: finding.path, type: finding.type });
  }
}


// --------------------------------------------------
// PIN DATA
// --------------------------------------------------

let pinDataNodesCleared = 0;

if (
  CLEAR_PIN_DATA &&
  sanitizedWorkflow.pinData &&
  typeof sanitizedWorkflow.pinData === 'object'
) {
  pinDataNodesCleared = Object.keys(sanitizedWorkflow.pinData).length;
  sanitizedWorkflow.pinData = {};
}


// --------------------------------------------------
// RESULT
// --------------------------------------------------
// The report never includes the original values.

return [
  {
    json: {
      sanitizedWorkflow,
      report: {
        totalRedactions: details.length,
        byType: redactedByType,
        pinDataNodesCleared,
        details
      }
    }
  }
];

const { sanitizedWorkflow, report } = $input.first().json;

// File name based on the workflow name, e.g.
// "WhatsApp Message Buffer" -> "whatsapp-message-buffer-sanitized.json"
const baseName =
  String(sanitizedWorkflow.name || 'workflow')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '') || 'workflow';

return [
  {
    json: {
      workflowText: JSON.stringify(sanitizedWorkflow, null, 2),
      fileName: `${baseName}-sanitized.json`,
      report
    }
  }
];
